using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "MyMcpServer", Version = "1.0.0" };
    })
    .WithHttpTransport()
    .WithTools<MyTools>()
    .WithResources<MyResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Adds two numbers together.")]
    public static int Add(int a, int b) => a + b;

    [McpServerTool, Description("Gets the current server time in UTC.")]
    public static string GetServerTime() => DateTime.UtcNow.ToString("O");
}

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(UriTemplate = "config://app",
        Name = "App Configuration",
        Description = "Returns the current application configuration.",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            environment = "production",
            version = "1.0.0",
            features = new { darkMode = true, betaAccess = false },
            maxConnections = 100
        };
        return System.Text.Json.JsonSerializer.Serialize(config);
    }

    [McpServerResource(UriTemplate = "config://app/features/{featureName}",
        Name = "Feature Flag",
        Description = "Returns the status of a specific feature flag.",
        MimeType = "application/json")]
    public static string GetFeatureFlag(string featureName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaAccess"] = false,
            ["notifications"] = true
        };

        var enabled = flags.TryGetValue(featureName, out var value) && value;
        return System.Text.Json.JsonSerializer.Serialize(new { featureName, enabled });
    }
}

